    this.targets.clear();
    this.interpreter.clear();
    this.isRunning = false;
    this.isPaused = false;
    this.tickCount = 0;
    this.taskQueue.clear();
    this.activeThreads = [];
    this.cloneCounter = 0;
    this.clonesByParent.clear();
    resetThreadCounter();

    // Reset Phase 6F Broadcast state
    this.pendingBroadcasts = [];
    this.broadcastTokens.clear();
    this.listenerRegistry.clear();
    this.broadcastsProcessedThisTick = 0;
    this.broadcastCounter = 0;

    // Reset Phase 7A Stage Sync state
    this.layerOrderList = [];

    // Reset Phase 7C Asset registries
    this.costumeRegistry.clear();
    this.soundRegistry.clear();
    this.backdropRegistry.clear();

    // Reset and Seed Phase 18B Component Asset Library
    this.componentAssetLibrary.clearAssets();
    this.componentAssetLibrary.seedDefaults();

    // Reset and Seed Phase 18C Breadboard Visual Rendering
    this.clearBreadboardVisuals();
