    // Reset Phase 7G Variable Watchers
    this.variableWatchers.clear();

    // Reset Phase 7H List Watchers
    this.listWatchers.clear();

    // Reset PRNG
    this.randomSeed = 1;

    // Reset Phase 7J Sensing state
